var _refundsState={page:1,limit:50};function _escR(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function _refundsQuery(){var v=function(id){var el=document.getElementById(id);return el?String(el.value||'').trim():'';};var qs=[];[['from','rfFrom'],['to','rfTo'],['method','rfMethod'],['status','rfStatus'],['type','rfType'],['search','rfSearch']].forEach(function(p){var x=v(p[1]);if(x)qs.push(p[0]+'='+encodeURIComponent(x));});return qs.join('&');}
function refundsFilterChanged(){_refundsState.page=1;loadRefundsSection();}
var _refundsSearchTimer=null;function refundsSearchInput(){clearTimeout(_refundsSearchTimer);_refundsSearchTimer=setTimeout(refundsFilterChanged,350);}
function resetRefundFilters(){['rfFrom','rfTo','rfMethod','rfStatus','rfType','rfSearch'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});refundsFilterChanged();}
function refundsPage(delta){_refundsState.page=Math.max(1,_refundsState.page+delta);loadRefundsSection();}
function exportRefundsCsv(){var q=_refundsQuery();var url=ATP_API+'/admin/refunds?'+(q?q+'&':'')+'format=csv';var name='atp-refunds-'+new Date().toISOString().slice(0,10)+'.csv';if(typeof _downloadAuthed==='function')return _downloadAuthed(url,name);window.open(url,'_blank');}
function loadRefundsSection(){var host=document.getElementById('refundsBody');if(!host)return;host.innerHTML='<div style="padding:30px;color:#555;text-align:center">Loading refunds…</div>';var q=_refundsQuery();var url=ATP_API+'/admin/refunds?page='+_refundsState.page+'&limit='+_refundsState.limit+(q?'&'+q:'');fetch(url,{headers:{Authorization:'Bearer '+getToken()}}).then(function(r){return r.json().then(function(b){return{ok:r.ok,body:b};});}).then(function(res){if(!res.ok)throw new Error((res.body&&res.body.error)||'Failed to load');renderRefunds(res.body||{});}).catch(function(e){host.innerHTML='<div style="padding:30px;color:#f87171;text-align:center">Failed to load refunds: '+_escR(e.message||e)+'</div>';});}
function _rfMoney(amount,currency){if(amount==null)return'—';return _escR((currency||'AED').toUpperCase())+' '+Number(amount).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});}
function _rfDate(d,withTime){if(!d)return'—';var dt=new Date(d);if(isNaN(dt.getTime()))return'—';var opts={day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Dubai'};if(withTime){opts.hour='2-digit';opts.minute='2-digit';}
return _escR(dt.toLocaleString('en-GB',opts));}
var _RF_STATUS_STYLE={refunded:{fg:'#A8FF00',bg:'rgba(168,255,0,.12)',border:'rgba(168,255,0,.35)',label:'Refunded'},failed:{fg:'#f87171',bg:'rgba(239,68,68,.12)',border:'rgba(239,68,68,.4)',label:'Failed'},pending:{fg:'#fbbf24',bg:'rgba(245,158,11,.12)',border:'rgba(245,158,11,.4)',label:'Pending'},released:{fg:'#93c5fd',bg:'rgba(59,130,246,.12)',border:'rgba(59,130,246,.4)',label:'Hold released'},};var _RF_METHOD_LABEL={card:'Card',points:'Points',wallet:'Wallet',mixed:'Points + wallet'};function _rfCard(label,value,color,sub){return'<div style="background:#0f0f0f;border:1px solid #1e1e1e;border-radius:10px;padding:14px">'+'<div style="font-size:10px;color:#888;letter-spacing:.1em;text-transform:uppercase;font-weight:600">'+label+'</div>'+'<div style="font-family:var(--ff-display,sans-serif);font-size:26px;font-weight:900;color:'+color+'">'+value+'</div>'+
(sub?'<div style="font-size:11px;color:#666;margin-top:2px">'+sub+'</div>':'')+'</div>';}
function renderRefunds(data){var host=document.getElementById('refundsBody');if(!host)return;var t=data.totals||{};var rows=data.refunds||[];var html='';var other=(t.other_currencies||[]).map(function(o){return _rfMoney(o.amount,o.currency);}).join(' · ');html+='<div class="rf-cards" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin-bottom:16px">'+
_rfCard('AED refunded',_rfMoney(t.aed_refunded||0,'AED'),'#A8FF00','Card '+_rfMoney(t.card_aed||0,'AED')+' · Wallet '+_rfMoney(t.wallet_aed||0,'AED')+(other?'<br>+ '+other:''))+
_rfCard('Points refunded',Number(t.points_refunded||0).toLocaleString('en-US')+' pts','#fff','Back in members’ balances')+
_rfCard('Refunds',Number(t.count||0).toLocaleString('en-US'),'#fff',(t.refunded||0)+' refunded · '+(t.released||0)+' hold'+(t.released===1?'':'s')+' released')+
_rfCard('Need attention',String((t.failed||0)+(t.pending||0)),(t.failed?'#f87171':'#fff'),(t.failed||0)+' failed · '+(t.pending||0)+' pending')+'</div>';if(data.shopify&&data.shopify.url){html+='<div style="font-size:12px;color:#888;margin-bottom:12px">🛍️ '+_escR(data.shopify.note)+' — <a href="'+_escR(data.shopify.url)+'" target="_blank" rel="noopener" style="color:#A8FF00">open refunded orders ↗</a></div>';}
if(data.log_ready===false){html+='<div style="font-size:12px;color:#fbbf24;margin-bottom:12px">The refunds log is still being created on the server. Refresh in a minute.</div>';}
html+='<div style="background:#0f0f0f;border:1px solid #1e1e1e;border-radius:10px;padding:0;overflow-x:auto">';if(!rows.length){html+='<div style="padding:40px;color:#555;text-align:center;font-size:13px">No refunds match these filters.</div>';}else{html+='<table class="admin-table" style="width:100%;border-collapse:collapse;font-size:12px;min-width:980px"><thead><tr style="text-align:left;color:#888;border-bottom:1px solid #1a1a1a">'+'<th style="padding:10px 12px">Date</th>'+'<th style="padding:10px 12px">Member</th>'+'<th style="padding:10px 12px">For</th>'+'<th style="padding:10px 12px">Method</th>'+'<th style="padding:10px 12px;text-align:right">Amount</th>'+'<th style="padding:10px 12px">Status</th>'+'<th style="padding:10px 12px">Reference</th>'+'<th style="padding:10px 12px">Email</th>'+'<th style="padding:10px 12px"></th>'+'</tr></thead><tbody>';rows.forEach(function(r){var st=_RF_STATUS_STYLE[r.status]||{fg:'#aaa',bg:'rgba(255,255,255,.06)',border:'rgba(255,255,255,.15)',label:r.status};var m=r.member||{};var w=r.what||{};var amountParts=[];if(r.amount!=null)amountParts.push(_rfMoney(r.amount,r.currency));if(r.points)amountParts.push(Number(r.points).toLocaleString('en-US')+' pts');var ref=r.stripe_refund_id||r.payment_intent||'';html+='<tr style="border-bottom:1px solid #141414;vertical-align:top">'+'<td style="padding:10px 12px;color:#ddd;white-space:nowrap">'+_rfDate(r.date,true)+'</td>'+'<td style="padding:10px 12px;color:#fff">'+_escR(m.name||'(no name)')+'<br><span style="color:#666;font-size:11px">'+_escR(m.email||'')+'</span>'+
(m.member_number?'<br><span style="color:#555;font-size:10px">'+_escR(m.member_number)+'</span>':'')+'</td>'+'<td style="padding:10px 12px;color:#ddd;max-width:240px">'+'<span style="font-size:10px;color:#888;text-transform:uppercase;letter-spacing:.06em">'+_escR(w.type_label||'')+'</span><br>'+
_escR(w.name||'—')+
(w.date?'<br><span style="color:#666;font-size:11px">'+_rfDate(w.date,true)+'</span>':'')+
(r.reason_label?'<br><span style="color:#555;font-size:11px">'+_escR(r.reason_label)+'</span>':'')+'</td>'+'<td style="padding:10px 12px;color:#ddd;white-space:nowrap">'+_escR(_RF_METHOD_LABEL[r.method]||r.method)+
(r.paid_before_points_reset?'<br><span title="Paid with points before the 7 Oct 2026 points reset — refunded in points anyway" style="font-size:10px;color:#fbbf24">paid pre-reset</span>':'')+'</td>'+'<td style="padding:10px 12px;color:#fff;font-weight:700;text-align:right;white-space:nowrap">'+(amountParts.join('<br>')||'—')+'</td>'+'<td style="padding:10px 12px;white-space:nowrap"><span style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:'+st.fg+';background:'+st.bg+';border:1px solid '+st.border+';padding:3px 8px;border-radius:10px">'+_escR(st.label)+'</span>'+
(r.error?'<div style="color:#f87171;font-size:11px;max-width:220px;white-space:normal;margin-top:4px">'+_escR(r.error)+'</div>':'')+'</td>'+'<td style="padding:10px 12px;font-size:11px">'+
(ref?'<span style="font-family:monospace;color:#aaa;word-break:break-all">'+_escR(ref)+'</span>':'<span style="color:#555">—</span>')+
(r.stripe_payment_url?'<br><a href="'+_escR(r.stripe_payment_url)+'" target="_blank" rel="noopener" style="color:#A8FF00">Stripe payment ↗</a>':'')+'</td>'+'<td style="padding:10px 12px;font-size:11px;white-space:nowrap">'+
(r.email_sent?'<span style="color:#A8FF00">✓ Sent</span><br><span style="color:#555">'+_rfDate(r.email_sent_at,true)+'</span>':(r.status==='refunded'?'<span style="color:#888" title="'+_escR(r.email_error||'')+'">Not sent</span>':'<span style="color:#555">—</span>'))+'</td>'+'<td style="padding:10px 12px;text-align:right">'+
(r.retry?'<button class="admin-btn admin-btn-primary" style="font-size:11px;padding:5px 10px;white-space:nowrap" data-atp-call="retryRefundFromList" data-args=\''+_escR(JSON.stringify([r.retry.booking_id]))+'\'>↻ Retry refund</button>':'')+'</td>'+'</tr>';});html+='</tbody></table>';}
html+='</div>';var total=data.total||0;var pages=Math.max(1,Math.ceil(total/(data.limit||_refundsState.limit)));html+='<div style="display:flex;justify-content:space-between;align-items:center;margin-top:12px;font-size:12px;color:#888">'+'<span>'+total.toLocaleString('en-US')+' refund'+(total===1?'':'s')+' · page '+_refundsState.page+' of '+pages+'</span>'+'<span style="display:flex;gap:8px">'+'<button class="admin-btn" style="font-size:11px;padding:6px 12px"'+(_refundsState.page<=1?' disabled':'')+' data-atp-call="refundsPage" data-args="[-1]">← Prev</button>'+'<button class="admin-btn" style="font-size:11px;padding:6px 12px"'+(_refundsState.page>=pages?' disabled':'')+' data-atp-call="refundsPage" data-args="[1]">Next →</button>'+'</span></div>';host.innerHTML=html;}
function retryRefundFromList(bookingId,btn){if(!bookingId||typeof bookingId!=='string')return;if(!confirm('Issue the card refund for this booking now? The member is emailed once it goes through.'))return;if(btn&&btn.tagName){btn.disabled=true;btn.textContent='Refunding…';}
fetch(ATP_API+'/bookings/'+encodeURIComponent(bookingId)+'/retry-refund',{method:'POST',headers:{Authorization:'Bearer '+getToken()},}).then(function(r){return r.json().then(function(b){return{ok:r.ok,body:b};});}).then(function(res){if(!res.ok||(res.body&&res.body.error)){showToast('❌ '+((res.body&&res.body.error)||'Refund failed'),true);}else if(res.body&&res.body.idempotent){showToast('ℹ️ Already refunded');}else{showToast('💸 Refund issued: '+(res.body.refunded_currency||'AED')+' '+Number(res.body.refunded_amount||0).toFixed(2));}
loadRefundsSection();}).catch(function(e){showToast('❌ '+e.message,true);loadRefundsSection();});}